--
-- REL-004 Lane C — the provider/template kill-switch policy document. NULLABLE with NO
-- DEFAULT on purpose: SQL NULL is "no policy has ever been set", which `evaluateKillSwitches`
-- permits, while a `DEFAULT '{}'::jsonb` would be a document that exists and cannot be
-- understood — i.e. the default alone would drain every worker fleet on every install.
-- The `aoa_app` SELECT grant that makes this readable from the poll path is migration 0261.
ALTER TABLE "instance_settings" ADD COLUMN IF NOT EXISTS "kill_switches" jsonb;
